// Load run: read the deterministic decomposition (glossary + batches) and set up an output dir.
// Input: webhook body {symbol?: "ABBV", run?: "run_2026-09-11", batches?: [0,1]} or manual trigger (full run).
// The LLM never sees prices, returns or the account: only glossary + batch JSON go forward.
const fs = require('fs');
const path = require('path');

const ROOT = 'C:/Users/ajwal/Documents/ai_agent_eval';
const MODEL = 'gemini-3.5-flash-lite';
const ADAPTER = `

## Runtime adapter (n8n)
You have no file tools in this runtime. The full contents of the files named above are
inlined in the user message between "=== <filename> ===" markers; treat them as the files.
Where the prompt says to write output to a file, return that JSON object as your ENTIRE
response instead (no prose, no code fences). Ignore any instruction to reply with a count.`;

const body = ($input.first().json.body) || {};
const srcRun = body.run || 'run_2026-09-11';
const srcDir = path.join(ROOT, srcRun);
const glossary = JSON.parse(fs.readFileSync(path.join(srcDir, 'glossary.json'), 'utf8'));
const writerPrompt = fs.readFileSync(path.join(srcDir, 'prompts', 'writer_prompt.md'), 'utf8');
const verifierPrompt = fs.readFileSync(path.join(srcDir, 'prompts', 'verifier_prompt.md'), 'utf8');

let batches = [];
for (let k = 0; fs.existsSync(path.join(srcDir, `batch_${k}.json`)); k++) {
  batches.push(JSON.parse(fs.readFileSync(path.join(srcDir, `batch_${k}.json`), 'utf8')).positions);
}
if (!batches.length) throw new Error(`no batch_k.json in ${srcDir}`);

const symbol = body.symbol ? String(body.symbol).toUpperCase().trim() : null;
if (symbol) {
  const pos = batches.flat().find(p => p.symbol === symbol);
  if (!pos) {
    return [{ json: { refused: true, message: `${symbol} is not a position in the ${glossary.asof} book.` } }];
  }
  batches = [[pos]];
} else if (Array.isArray(body.batches)) {
  batches = body.batches.map(k => batches[k]);
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const outDir = path.join(ROOT, 'runs', `n8n_${glossary.asof}_${symbol || 'full'}_${stamp}`).replace(/\\/g, '/');
fs.mkdirSync(outDir, { recursive: true });
fs.copyFileSync(path.join(srcDir, 'glossary.json'), path.join(outDir, 'glossary.json'));

return batches.map((positions, k) => {
  fs.writeFileSync(path.join(outDir, `batch_${k}.json`), JSON.stringify({ positions }));
  // Only this batch's company backgrounds are inlined (the rest of the glossary is unchanged).
  const syms = new Set(positions.map(p => p.symbol));
  const g = { ...glossary, backgrounds: Object.fromEntries(Object.entries(glossary.backgrounds).filter(([s]) => syms.has(s))) };
  const files = `=== glossary.json ===\n${JSON.stringify(g)}\n\n=== batch_${k}.json ===\n${JSON.stringify({ positions })}`;
  return {
    json: {
      refused: false, k, outDir, model: MODEL, asof: glossary.asof, symbols: [...syms],
      writerSystem: writerPrompt.replaceAll('{S}', '.').replaceAll('{k}', String(k)) + ADAPTER,
      verifierSystem: verifierPrompt.replaceAll('{S}', '.').replaceAll('{k}', String(k)) + ADAPTER,
      files, glossaryForVerifier: JSON.stringify(g), batchJson: JSON.stringify({ positions }),
      t_writer_start: Date.now(),
    },
  };
});

// Parse writer output -> draft_k.json; build the verifier request for the same batch.
const fs = require('fs');
const out = [];
for (const item of $input.all()) {
  const req = $('Loop over batches').item.json;   // the batch this response belongs to
  const r = item.json;
  const text = (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
  let draft;
  try {
    draft = JSON.parse(text.replace(/^```(json)?\s*|\s*```$/g, ''));
  } catch (e) {
    throw new Error(`writer returned non-JSON for batch ${req.k}: ${text.slice(0, 300)}`);
  }
  if (Array.isArray(draft)) draft = { explanations: draft };
  fs.writeFileSync(`${req.outDir}/draft_${req.k}.json`, JSON.stringify(draft, null, 1));
  const u = r.usageMetadata || {};
  out.push({
    json: {
      ...req,
      draftJson: JSON.stringify(draft),
      writer: { ms: Date.now() - req.t_writer_start, in_tokens: u.promptTokenCount || 0,
                out_tokens: (u.candidatesTokenCount || 0) + (u.thoughtsTokenCount || 0), n_cards: (draft.explanations || []).length },
      verifierUser: `=== glossary.json ===\n${req.glossaryForVerifier}\n\n=== batch_${req.k}.json ===\n${req.batchJson}\n\n=== draft_${req.k}.json ===\n${JSON.stringify(draft)}`,
      t_verifier_start: Date.now(),
    },
  });
}
return out;

// Parse verifier output -> verified_k.json (the guard node reads it from disk next).
const fs = require('fs');
const out = [];
for (const item of $input.all()) {
  const req = $('Parse draft').item.json;
  const r = item.json;
  const text = (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
  let ver;
  try {
    ver = JSON.parse(text.replace(/^```(json)?\s*|\s*```$/g, ''));
  } catch (e) {
    throw new Error(`verifier returned non-JSON for batch ${req.k}: ${text.slice(0, 300)}`);
  }
  if (Array.isArray(ver)) ver = { results: ver };
  fs.writeFileSync(`${req.outDir}/verified_${req.k}.json`, JSON.stringify(ver, null, 1));
  const u = r.usageMetadata || {};
  const results = ver.results || [];
  out.push({
    json: {
      k: req.k, outDir: req.outDir, asof: req.asof, model: req.model, symbols: req.symbols,
      writer: req.writer,
      verifier: { ms: Date.now() - req.t_verifier_start, in_tokens: u.promptTokenCount || 0,
                  out_tokens: (u.candidatesTokenCount || 0) + (u.thoughtsTokenCount || 0),
                  n_checked: results.length, n_corrected: results.filter(x => x.ok === false).length },
    },
  });
}
return out;

// Attach the deterministic guard's verdict (stdout of guard_cli.py) to the batch record.
return $input.all().map(item => {
  const prev = $('Parse verified').item.json;
  let guard;
  try {
    guard = JSON.parse(item.json.stdout);
  } catch (e) {
    guard = { error: `guard failed: ${(item.json.stderr || item.json.stdout || '').slice(0, 400)}`, cards: {}, n_pass: 0, n: 0 };
  }
  return { json: { ...prev, guard } };
});

// Merge every batch into explanations.json (+ run_metrics.json) and return the cards.
// A card's text is the verifier's corrected text; guard failures are attached, never hidden.
const fs = require('fs');
const batches = $input.all().map(i => i.json);
if (!batches.length) return [{ json: { error: 'no batches completed' } }];
const outDir = batches[0].outDir;
const explanations = {};
const cards = [];
for (const b of batches) {
  const ver = JSON.parse(fs.readFileSync(`${outDir}/verified_${b.k}.json`, 'utf8')).results || [];
  const pos = JSON.parse(fs.readFileSync(`${outDir}/batch_${b.k}.json`, 'utf8')).positions;
  for (const v of ver) {
    const p = pos.find(x => x.symbol === v.symbol) || {};
    const g = b.guard.cards?.[v.symbol] || { pass: false, fails: [{ check: 'guard_missing' }] };
    const card = {
      symbol: v.symbol, side: p.position > 0 ? 'long' : 'short', target_dollars: p.target_dollars,
      entry_date: p.entry_date, agg_z: p.entry?.agg_z, n_sources: p.entry?.n_sources,
      headline: v.corrected_headline, body: v.corrected_body, drivers: v.drivers, dissenters: v.dissenters,
      status_today: v.status_today, verify_problems: v.problems || [], verifier_ok: v.ok,
      guard_pass: g.pass, guard_fails: g.fails, company_fact_unsupported: g.company_fact_unsupported || [],
    };
    explanations[v.symbol] = card;
    cards.push(card);
  }
}
const n = cards.length || 1;
const sum = (f) => batches.reduce((a, b) => a + f(b), 0);
const metrics = {
  asof: batches[0].asof, model: batches[0].model, outDir, positions: cards.length,
  corrected_by_verifier: cards.filter(c => c.verifier_ok === false).length,
  guard_pass: cards.filter(c => c.guard_pass).length,
  tokens_in: sum(b => b.writer.in_tokens + b.verifier.in_tokens),
  tokens_out: sum(b => b.writer.out_tokens + b.verifier.out_tokens),
  seconds_llm: sum(b => b.writer.ms + b.verifier.ms) / 1000,
  per_position: {
    tokens_in: Math.round(sum(b => b.writer.in_tokens + b.verifier.in_tokens) / n),
    tokens_out: Math.round(sum(b => b.writer.out_tokens + b.verifier.out_tokens) / n),
    seconds: +(sum(b => b.writer.ms + b.verifier.ms) / 1000 / n).toFixed(2),
  },
  batches: batches.map(b => ({ k: b.k, symbols: b.symbols, writer: b.writer, verifier: b.verifier,
                               guard_pass: b.guard.n_pass, guard_n: b.guard.n, guard_error: b.guard.error })),
};
fs.writeFileSync(`${outDir}/explanations.json`, JSON.stringify(explanations, null, 1));
fs.writeFileSync(`${outDir}/run_metrics.json`, JSON.stringify(metrics, null, 1));
fs.writeFileSync('C:/Users/ajwal/Documents/ai_agent_eval/runs/LATEST.txt', outDir);
return [{ json: { metrics, cards } }];
